#!/usr/bin/env bash
# Complete FS-02 measurement run against the lab (scripts/lab.sh init|pg|pgbouncer|pgdog|odyssey|supavisor|pgcat|pgpool
# must be up, images built). Everything under results/ except docs-sha256.txt is regenerated by this script.
set -euo pipefail
HERE="$(cd "$(dirname "$0")/.." && pwd)"
set -a; . "$HERE/work/run.env"; set +a
cd "$HERE"
rm -rf results/cells.json results/matrix.csv results/raw results/oracle-psql.csv results/oracle-psql-beta3.csv results/oracle-faults.csv results/optional results/images.json results/grease-bytes.json results/summary.md results/tables
mkdir -p results/optional
BETA=(--image postgres:19beta3 --container fs02-psql-beta --mpvs default --file oracle-psql-beta3.csv)
bun scripts/matrix.ts --diag
bun scripts/matrix.ts --tier B
bun scripts/oracle-psql.ts
bun scripts/oracle-psql.ts --tier B
bun scripts/oracle-psql.ts "${BETA[@]}"
bun scripts/oracle-psql.ts --tier B "${BETA[@]}"
bun scripts/oracle-faults.ts
bun scripts/grease-bytes.ts > /dev/null
# optional endpoints: PgCat answers only the startup packet (MD5 client auth); pgpool-II is repeated to measure intermittency
bun scripts/probe.ts --host 127.0.0.1 --port 6500 --user fs02 --database t19 --id pgcat-latest-tran-pg19 --json > results/optional/pgcat-t19.json
bun scripts/probe.ts --host 127.0.0.1 --port 6500 --user fs02 --database s17 --id pgcat-latest-sess-pg17 --json > results/optional/pgcat-s17.json
bun scripts/repeat.ts --endpoint pgpool-4.7.3-pg19 --requests R0,R1,R2,R3,R4,R5,R6 --n 20 --beta3-psql 40 > /dev/null
bun scripts/repeat.ts --endpoint pgpool-4.7.3-pg17 --requests R0,R1,R2,R3,R4,R5 --n 20 > /dev/null
scripts/pgbouncer-cold.sh > results/optional/pgbouncer-cold.txt 2>&1
bun scripts/record-images.ts > /dev/null
bun scripts/report.ts > /dev/null
bun scripts/build-readme.ts
